{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "Haloperidol, the closest retrieved analogue, has absolute oral bioavailability of 70 ± 18% in humans, supporting high F for a similarly lipophilic aryl halide with a basic amine side chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Procainamide, a direct benzamide analogue with a basic aminoethyl side chain, has oral bioavailability of about 85%, supporting high absorption and limited first-pass loss for the query's benzamide-morpholine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "N-Acetylprocainamide, another para-substituted benzamide with a basic side chain, has absolute oral bioavailability of 87%, reinforcing high F for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Sematilide, a para-sulfonamide benzamide with a basic ethylamino side chain, has absolute oral bioavailability of 46%, still well above the 20% threshold and consistent with high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Indoramin, a more lipophilic basic amide, has median oral bioavailability of 23.6% (range 2.1-77.2%), showing that even high first-pass compounds in this broad class can meet the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Loperamide has very low absolute oral bioavailability (0.3%) due to P-gp efflux and first-pass metabolism, but its much larger, highly lipophilic structure and distinct transporter liability make it a weak contradictory analogue for this small benzamide.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small para-chlorobenzamide with a morpholine-ethyl side chain, closely related to procainamide and N-acetylprocainamide, both of which have high oral bioavailability (75-87%). Additional benzamide/basic-amine analogues (haloperidol, sematilide, indoramin) also meet or exceed 20% F. The only low-F analogue, loperamide, is structurally distant and its low F is driven by P-gp efflux not expected for this smaller, less lipophilic molecule. Therefore F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The retrieved analogues have moderate Morgan similarity (0.28-0.34), so transferability is limited.",
    "First-pass metabolism and transporter efflux of the morpholine-ethyl benzamide are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

